-- 0001_init.sql
-- Target: PostgreSQL 15+ with the pgvector extension.
--
-- Conventions (see ADR-0001, ADR-0007, ADR-0008):
--   * IDs are UUIDv7 generated by the application (time-ordered). No DB default on purpose,
--     so we do not depend on a specific Postgres version.
--   * Every user-owned table has user_id (future shard/partition key). Foreign keys exist only
--     WITHIN a module. Cross-module references are plain uuid columns. Account deletion is
--     therefore performed by an explicit hard-delete task, not by cascading from users.
--   * Enumerations are text + CHECK so they can evolve without type migrations.
--   * Heavy append-only tables are range-partitioned by month. Use pg_partman (or a scheduled
--     job) to create future partitions. A DEFAULT partition catches anything unexpected.
--   * No resume content or contact details are ever written to audit_log or task_events.

BEGIN;

CREATE EXTENSION IF NOT EXISTS vector;

CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- ===========================================================================
-- identity module
-- ===========================================================================

CREATE TABLE users (
  id                    uuid PRIMARY KEY,
  home_region           text NOT NULL DEFAULT 'in' CHECK (home_region ~ '^[a-z]{2,8}$'),
  auth_subject          text NOT NULL UNIQUE,            -- subject claim from the OIDC provider
  display_name          text,
  -- Contact fields are encrypted in the application (KMS). *_hash is a keyed HMAC blind index
  -- used for lookup and uniqueness without decrypting.
  email_enc             bytea,
  email_hash            bytea,
  phone_enc             bytea,
  phone_hash            bytea,
  ui_locale             text NOT NULL DEFAULT 'en-IN',
  plan_code             text NOT NULL DEFAULT 'free',
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  deletion_requested_at timestamptz,
  deleted_at            timestamptz
);
CREATE UNIQUE INDEX users_email_hash_uq ON users (email_hash)
  WHERE email_hash IS NOT NULL AND deleted_at IS NULL;
CREATE UNIQUE INDEX users_phone_hash_uq ON users (phone_hash)
  WHERE phone_hash IS NOT NULL AND deleted_at IS NULL;
CREATE TRIGGER users_set_updated_at BEFORE UPDATE ON users
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE consents (
  id             uuid PRIMARY KEY,
  user_id        uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  purpose        text NOT NULL CHECK (purpose IN ('account', 'ai_processing', 'analytics', 'marketing')),
  policy_version text NOT NULL,
  granted_at     timestamptz NOT NULL DEFAULT now(),
  withdrawn_at   timestamptz,
  source         text NOT NULL DEFAULT 'app' CHECK (source IN ('web', 'app', 'support'))
);
CREATE INDEX consents_user_purpose_idx ON consents (user_id, purpose, granted_at DESC);

-- ===========================================================================
-- billing module (plans are data, not code; prices per currency live in JSON)
-- ===========================================================================

CREATE TABLE plans (
  code    text PRIMARY KEY,
  name    text NOT NULL,
  limits  jsonb NOT NULL,   -- for example {"score_runs_per_month": 5, "tailorings_per_month": 2}
  prices  jsonb NOT NULL DEFAULT '{}'::jsonb,  -- {"INR": {...}, "USD": {...}}; filled by product
  active  boolean NOT NULL DEFAULT true
);
-- Limits below are placeholders for product to set. Prices are intentionally empty.
INSERT INTO plans (code, name, limits) VALUES
  ('free', 'Free', '{"score_runs_per_month": 5, "tailorings_per_month": 1}'),
  ('pro',  'Pro',  '{"score_runs_per_month": 100, "tailorings_per_month": 50}');

CREATE TABLE usage_counters (
  user_id  uuid NOT NULL,
  period   text NOT NULL CHECK (period ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
  metric   text NOT NULL,
  count    integer NOT NULL DEFAULT 0 CHECK (count >= 0),
  PRIMARY KEY (user_id, period, metric)
);

-- ===========================================================================
-- profile module: the master profile the user fills in once
-- ===========================================================================

CREATE TABLE profiles (
  user_id        uuid PRIMARY KEY,
  data           jsonb NOT NULL,                 -- validated against resume.schema.json
  schema_version text NOT NULL,
  version        integer NOT NULL DEFAULT 1,     -- optimistic concurrency token
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now()
);
CREATE TRIGGER profiles_set_updated_at BEFORE UPDATE ON profiles
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ===========================================================================
-- job-descriptions module
-- ===========================================================================

CREATE TABLE job_descriptions (
  id           uuid PRIMARY KEY,
  user_id      uuid NOT NULL,
  title        text,
  company      text,
  location     text,
  source_url   text,
  raw_text     text NOT NULL,
  parsed       jsonb,                              -- structured JD (skills, seniority, ...), set by parse task
  content_hash bytea NOT NULL,                     -- hash of normalised raw_text, used for dedupe and cache keys
  created_at   timestamptz NOT NULL DEFAULT now(),
  deleted_at   timestamptz
);
CREATE UNIQUE INDEX job_descriptions_user_hash_uq ON job_descriptions (user_id, content_hash)
  WHERE deleted_at IS NULL;
CREATE INDEX job_descriptions_user_created_idx ON job_descriptions (user_id, created_at DESC, id DESC);

-- ===========================================================================
-- resume module: resumes own immutable versions
-- ===========================================================================

CREATE TABLE resumes (
  id                  uuid PRIMARY KEY,
  user_id             uuid NOT NULL,
  title               text NOT NULL,
  kind                text NOT NULL CHECK (kind IN ('base', 'tailored')),
  job_description_id  uuid,                        -- cross-module reference, no FK
  current_version_id  uuid,                        -- points into resume_versions, no FK (avoids a cycle)
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  deleted_at          timestamptz
);
CREATE INDEX resumes_user_created_idx ON resumes (user_id, created_at DESC, id DESC)
  WHERE deleted_at IS NULL;
CREATE TRIGGER resumes_set_updated_at BEFORE UPDATE ON resumes
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE resume_versions (
  id                      uuid PRIMARY KEY,
  resume_id               uuid NOT NULL REFERENCES resumes (id) ON DELETE CASCADE,
  user_id                 uuid NOT NULL,
  version_no              integer NOT NULL CHECK (version_no > 0),
  content                 jsonb NOT NULL,          -- validated against resume.schema.json
  schema_version          text NOT NULL,
  origin                  text NOT NULL CHECK (origin IN ('user', 'import', 'ai_tailor')),
  status                  text NOT NULL DEFAULT 'approved'
                            CHECK (status IN ('draft', 'pending_approval', 'approved', 'rejected')),
  derived_from_version_id uuid,
  template_id             text,
  created_at              timestamptz NOT NULL DEFAULT now(),
  UNIQUE (resume_id, version_no)
);
CREATE INDEX resume_versions_user_idx ON resume_versions (user_id, created_at DESC);

-- Versions are immutable. Only `status` may change (pending_approval -> approved/rejected).
CREATE OR REPLACE FUNCTION resume_versions_immutable() RETURNS trigger AS $$
BEGIN
  IF NEW.content IS DISTINCT FROM OLD.content
     OR NEW.resume_id IS DISTINCT FROM OLD.resume_id
     OR NEW.user_id IS DISTINCT FROM OLD.user_id
     OR NEW.version_no IS DISTINCT FROM OLD.version_no
     OR NEW.origin IS DISTINCT FROM OLD.origin
     OR NEW.derived_from_version_id IS DISTINCT FROM OLD.derived_from_version_id THEN
    RAISE EXCEPTION 'resume_versions rows are immutable except for status and template_id';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER resume_versions_no_update BEFORE UPDATE ON resume_versions
  FOR EACH ROW EXECUTE FUNCTION resume_versions_immutable();

-- ===========================================================================
-- shared infrastructure: async tasks and outbox (ADR-0004)
-- ===========================================================================

CREATE TABLE async_tasks (
  id               uuid PRIMARY KEY,
  user_id          uuid NOT NULL,
  type             text NOT NULL CHECK (type IN ('parse_resume', 'parse_jd', 'score', 'tailor', 'render', 'export', 'delete_account')),
  status           text NOT NULL DEFAULT 'queued'
                     CHECK (status IN ('queued', 'running', 'retrying', 'succeeded', 'failed', 'cancelled')),
  idempotency_key  text NOT NULL,
  input            jsonb NOT NULL DEFAULT '{}'::jsonb,   -- ids and options only, never raw resume text
  result           jsonb,                                -- ids of produced rows (score_run_id, resume_version_id, file key)
  error            jsonb,                                -- {code, message} with no PII
  attempts         integer NOT NULL DEFAULT 0,
  max_attempts     integer NOT NULL DEFAULT 5,
  trace_id         text,
  created_at       timestamptz NOT NULL DEFAULT now(),
  started_at       timestamptz,
  finished_at      timestamptz,
  updated_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, idempotency_key)
);
CREATE INDEX async_tasks_user_created_idx ON async_tasks (user_id, created_at DESC, id DESC);
CREATE INDEX async_tasks_pending_idx ON async_tasks (created_at) WHERE status IN ('queued', 'retrying');
CREATE TRIGGER async_tasks_set_updated_at BEFORE UPDATE ON async_tasks
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE outbox_events (
  id             uuid PRIMARY KEY,
  aggregate_type text NOT NULL,
  aggregate_id   uuid NOT NULL,
  event_type     text NOT NULL,
  payload        jsonb NOT NULL,
  created_at     timestamptz NOT NULL DEFAULT now(),
  published_at   timestamptz,
  attempts       integer NOT NULL DEFAULT 0
);
CREATE INDEX outbox_unpublished_idx ON outbox_events (created_at) WHERE published_at IS NULL;

-- ===========================================================================
-- append-only, partitioned by month
-- ===========================================================================

CREATE TABLE task_events (
  id         uuid NOT NULL,
  task_id    uuid NOT NULL,
  user_id    uuid NOT NULL,
  from_status text,
  to_status  text NOT NULL,
  detail     jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (id, created_at)
) PARTITION BY RANGE (created_at);
CREATE TABLE task_events_default PARTITION OF task_events DEFAULT;
CREATE INDEX task_events_task_idx ON task_events (task_id, created_at);

CREATE TABLE score_runs (
  id                  uuid NOT NULL,
  user_id             uuid NOT NULL,
  resume_version_id   uuid NOT NULL,
  job_description_id  uuid,                        -- null for a format-only ATS-readiness check
  overall             smallint NOT NULL CHECK (overall BETWEEN 0 AND 100),
  breakdown           jsonb NOT NULL,              -- per-component scores (skills, semantic, rubric, format)
  findings            jsonb NOT NULL DEFAULT '[]'::jsonb,  -- explanations and suggested fixes
  scoring_version     text NOT NULL,
  model_versions      jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at          timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (id, created_at)
) PARTITION BY RANGE (created_at);
CREATE TABLE score_runs_default PARTITION OF score_runs DEFAULT;
CREATE INDEX score_runs_user_idx ON score_runs (user_id, created_at DESC);
CREATE INDEX score_runs_version_idx ON score_runs (resume_version_id, created_at DESC);

CREATE TABLE audit_log (
  id            uuid NOT NULL,
  user_id       uuid,
  actor         text NOT NULL,                     -- 'user', 'system', or a service name
  action        text NOT NULL,                     -- for example 'consent.granted', 'account.deleted'
  resource_type text,
  resource_id   uuid,
  detail        jsonb,                             -- metadata only, never content or contact details
  created_at    timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (id, created_at)
) PARTITION BY RANGE (created_at);
CREATE TABLE audit_log_default PARTITION OF audit_log DEFAULT;
CREATE INDEX audit_log_user_idx ON audit_log (user_id, created_at DESC);

-- ===========================================================================
-- embeddings (pgvector)
-- The dimension is tied to the embedding model chosen in ADR-0006. Confirm the model BEFORE
-- applying this migration to a shared environment. Changing it later means a new column or
-- table plus a backfill.
-- ===========================================================================

CREATE TABLE embeddings (
  id           uuid PRIMARY KEY,
  user_id      uuid NOT NULL,
  owner_type   text NOT NULL CHECK (owner_type IN ('profile_item', 'resume_section', 'jd_section')),
  owner_id     uuid NOT NULL,
  model        text NOT NULL,
  content_hash bytea NOT NULL,
  embedding    vector(1024) NOT NULL,
  created_at   timestamptz NOT NULL DEFAULT now(),
  UNIQUE (owner_type, owner_id, model, content_hash)
);
CREATE INDEX embeddings_user_idx ON embeddings (user_id);
CREATE INDEX embeddings_hnsw_idx ON embeddings USING hnsw (embedding vector_cosine_ops);

COMMIT;
